[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ScreenVault — UI & UX design inspiration for mobile & web apps</title>
  <meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --primary-dark: #141414;
      --bg-white: #FFFFFF;
      --surface-gray: #F5F5F5;
      --accent: #6C5CE7;
      --accent-hover: #5A4BD1;
      --text-secondary: #6B7280;
      --border: #E5E7EB;
      --radius: 12px;
      --radius-sm: 8px;
      --radius-pill: 100px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
      --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--primary-dark);
      background: var(--bg-white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== Announcement Bar ===== */
    .announcement-bar {
      background: var(--primary-dark);
      color: #fff;
      text-align: center;
      padding: 10px 24px;
      font-size: 13px;
      font-weight: 500;
      letter-spacing: 0.02em;
    }

    .announcement-bar a {
      color: var(--accent);
      text-decoration: none;
      margin-left: 6px;
    }

    /* ===== Header/Nav ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }

    .header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--primary-dark);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 32px;
      height: 32px;
      background: var(--accent);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 18px; height: 18px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      transition: color var(--transition);
    }

    .nav-links a:hover { color: var(--primary-dark); }

    .nav-links .btn-login {
      color: var(--primary-dark);
      font-weight: 600;
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-menu-btn span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--primary-dark);
      margin: 5px 0;
      transition: var(--transition);
    }

    /* ===== Hero ===== */
    .hero {
      padding: 80px 0 60px;
      text-align: center;
    }

    .hero h1 {
      font-size: clamp(36px, 5.5vw, 64px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
      margin-bottom: 20px;
      max-width: 720px;
      margin-left: auto;
      margin-right: auto;
    }

    .hero p {
      font-size: clamp(16px, 2vw, 19px);
      color: var(--text-secondary);
      max-width: 540px;
      margin: 0 auto 36px;
      line-height: 1.6;
    }

    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--accent);
      color: #fff;
      padding: 14px 28px;
      border-radius: var(--radius-pill);
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      border: none;
      cursor: pointer;
      transition: background var(--transition), transform var(--transition);
    }

    .btn-primary:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
    }

    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: transparent;
      color: var(--primary-dark);
      padding: 14px 28px;
      border-radius: var(--radius-pill);
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      border: 1.5px solid var(--border);
      cursor: pointer;
      transition: border-color var(--transition), transform var(--transition);
    }

    .btn-secondary:hover {
      border-color: var(--primary-dark);
      transform: translateY(-1px);
    }

    /* ===== Trusted By ===== */
    .trusted-by {
      padding: 40px 0 60px;
      text-align: center;
    }

    .trusted-by p {
      font-size: 13px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-secondary);
      margin-bottom: 28px;
    }

    .brand-logos {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-wrap: wrap;
      gap: 36px;
    }

    .brand-logo {
      font-size: 18px;
      font-weight: 700;
      color: #C0C0C0;
      letter-spacing: -0.01em;
      user-select: none;
    }

    /* ===== Stats ===== */
    .stats {
      padding: 80px 0;
      background: var(--surface-gray);
    }

    .stats .container { text-align: center; }

    .stats-label {
      font-size: 14px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-secondary);
      margin-bottom: 48px;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      max-width: 800px;
      margin: 0 auto;
    }

    .stat-item h3 {
      font-size: clamp(40px, 6vw, 64px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1;
      margin-bottom: 8px;
      color: var(--primary-dark);
    }

    .stat-item p {
      font-size: 15px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    /* ===== Feature Search ===== */
    .features-search {
      padding: 100px 0;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 17px;
      color: var(--text-secondary);
      max-width: 520px;
      margin: 0 auto;
    }

    .search-tabs {
      display: flex;
      justify-content: center;
      gap: 4px;
      margin-bottom: 24px;
      background: var(--surface-gray);
      border-radius: var(--radius-pill);
      padding: 4px;
      display: inline-flex;
      margin-left: auto;
      margin-right: auto;
    }

    .search-tabs-wrap { text-align: center; margin-bottom: 24px; }

    .search-tab {
      padding: 10px 20px;
      border-radius: var(--radius-pill);
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      cursor: pointer;
      border: none;
      background: transparent;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .search-tab.active {
      background: var(--bg-white);
      color: var(--primary-dark);
      box-shadow: var(--shadow-sm);
      font-weight: 600;
    }

    .search-tab:hover:not(.active) { color: var(--primary-dark); }

    .filter-pills {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 8px;
      margin-bottom: 32px;
      scrollbar-width: none;
      justify-content: center;
      flex-wrap: wrap;
    }

    .filter-pills::-webkit-scrollbar { display: none; }

    .filter-pill {
      padding: 8px 18px;
      border-radius: var(--radius-pill);
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      border: 1.5px solid var(--border);
      background: var(--bg-white);
      cursor: pointer;
      transition: all var(--transition);
      white-space: nowrap;
      flex-shrink: 0;
    }

    .filter-pill.active {
      background: var(--primary-dark);
      color: #fff;
      border-color: var(--primary-dark);
    }

    .filter-pill:hover:not(.active) {
      border-color: var(--primary-dark);
      color: var(--primary-dark);
    }

    .screenshot-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .screenshot-card {
      background: var(--surface-gray);
      border-radius: var(--radius);
      aspect-ratio: 9/16;
      overflow: hidden;
      position: relative;
      transition: transform var(--transition), box-shadow var(--transition);
      cursor: pointer;
    }

    .screenshot-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .screenshot-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      padding: 16px;
      justify-content: space-between;
    }

    .screenshot-placeholder .ph-bar {
      height: 8px;
      background: rgba(0,0,0,0.06);
      border-radius: 4px;
    }

    .screenshot-placeholder .ph-bar.short { width: 60%; }
    .screenshot-placeholder .ph-bar.medium { width: 80%; }

    .screenshot-placeholder .ph-circle {
      width: 28px;
      height: 28px;
      background: rgba(0,0,0,0.06);
      border-radius: 50%;
    }

    .screenshot-placeholder .ph-header {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .screenshot-placeholder .ph-body {
      display: flex;
      flex-direction: column;
      gap: 8px;
      flex: 1;
      justify-content: center;
    }

    .screenshot-placeholder .ph-rect {
      width: 100%;
      height: 40px;
      background: rgba(0,0,0,0.04);
      border-radius: 8px;
    }

    .screenshot-card-label {
      position: absolute;
      bottom: 12px;
      left: 12px;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(8px);
      padding: 4px 10px;
      border-radius: var(--radius-pill);
      font-size: 11px;
      font-weight: 600;
      color: var(--primary-dark);
    }

    /* ===== Features Flows ===== */
    .features-flows {
      padding: 100px 0;
      background: var(--surface-gray);
    }

    .flows-toggle-wrap {
      display: flex;
      justify-content: center;
      margin-bottom: 40px;
    }

    .flows-toggle {
      display: inline-flex;
      background: var(--bg-white);
      border-radius: var(--radius-pill);
      padding: 4px;
      gap: 4px;
      box-shadow: var(--shadow-sm);
    }

    .flows-toggle-btn {
      padding: 10px 24px;
      border-radius: var(--radius-pill);
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border: none;
      background: transparent;
      cursor: pointer;
      transition: all var(--transition);
    }

    .flows-toggle-btn.active {
      background: var(--primary-dark);
      color: #fff;
    }

    .flows-content {
      max-width: 900px;
      margin: 0 auto;
    }

    .flows-panel {
      display: none;
      animation: fadeIn 300ms ease;
    }

    .flows-panel.active { display: block; }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .flows-visual {
      background: var(--bg-white);
      border-radius: 16px;
      padding: 40px;
      box-shadow: var(--shadow-md);
    }

    .flows-steps {
      display: flex;
      gap: 16px;
      overflow-x: auto;
      padding-bottom: 8px;
    }

    .flow-step {
      flex-shrink: 0;
      width: 140px;
      height: 260px;
      background: var(--surface-gray);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    .flow-step::after {
      content: '';
      position: absolute;
      right: -12px;
      top: 50%;
      transform: translateY(-50%);
      width: 8px;
      height: 8px;
      border-right: 2px solid var(--accent);
      border-bottom: 2px solid var(--accent);
      transform: translateY(-50%) rotate(-45deg);
    }

    .flow-step:last-child::after { display: none; }

    .flow-step-num {
      font-size: 20px;
      font-weight: 700;
      color: rgba(0,0,0,0.1);
    }

    .video-placeholder {
      aspect-ratio: 16/9;
      background: var(--bg-white);
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      position: relative;
      overflow: hidden;
    }

    .video-placeholder::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(108,92,231,0.05), rgba(108,92,231,0.15));
    }

    .play-btn {
      width: 64px;
      height: 64px;
      background: var(--accent);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1;
      box-shadow: 0 4px 24px rgba(108,92,231,0.3);
    }

    .play-btn svg { width: 24px; height: 24px; fill: #fff; margin-left: 3px; }

    .flows-desc {
      text-align: center;
      margin-top: 20px;
      font-size: 15px;
      color: var(--text-secondary);
    }

    /* ===== Features Tools ===== */
    .features-tools {
      padding: 100px 0;
    }

    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .tool-card {
      background: var(--surface-gray);
      border-radius: 16px;
      padding: 32px;
      transition: transform var(--transition), box-shadow var(--transition);
    }

    .tool-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .tool-icon {
      width: 48px;
      height: 48px;
      background: var(--accent);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .tool-icon svg { width: 24px; height: 24px; }

    .tool-card h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .tool-card p {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    .tool-preview {
      width: 100%;
      height: 160px;
      background: var(--bg-white);
      border-radius: var(--radius);
      margin-top: 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .tool-preview-content {
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 16px;
      width: 100%;
    }

    .tool-preview-row {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .tool-preview-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .tool-preview-line {
      height: 6px;
      border-radius: 3px;
      background: var(--surface-gray);
    }

    /* ===== Testimonials ===== */
    .testimonials {
      padding: 100px 0;
      background: var(--surface-gray);
      overflow: hidden;
    }

    .testimonials-track-wrapper {
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    .testimonials-track {
      display: flex;
      gap: 20px;
      animation: marquee-left 40s linear infinite;
      width: max-content;
    }

    .testimonials-track.reverse {
      animation: marquee-right 45s linear infinite;
    }

    @keyframes marquee-left {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    @keyframes marquee-right {
      0% { transform: translateX(-50%); }
      100% { transform: translateX(0); }
    }

    .testimonial-card {
      flex-shrink: 0;
      width: 380px;
      background: var(--bg-white);
      border-radius: 16px;
      padding: 28px;
      box-shadow: var(--shadow-sm);
    }

    .testimonial-header {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 16px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--accent);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      font-weight: 700;
      color: #fff;
    }

    .testimonial-name {
      font-size: 14px;
      font-weight: 700;
    }

    .testimonial-company {
      font-size: 12px;
      color: var(--text-secondary);
    }

    .testimonial-text {
      font-size: 14px;
      line-height: 1.65;
      color: #444;
    }

    /* ===== CTA Section ===== */
    .cta-section {
      padding: 100px 0 60px;
      text-align: center;
    }

    .cta-section h2 {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 16px;
    }

    .cta-section > .container > p {
      font-size: 17px;
      color: var(--text-secondary);
      max-width: 520px;
      margin: 0 auto 36px;
    }

    .cta-buttons {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 60px;
    }

    .icon-marquee-wrapper {
      overflow: hidden;
      padding: 20px 0;
    }

    .icon-marquee-row {
      display: flex;
      gap: 24px;
      width: max-content;
      animation: marquee-left 35s linear infinite;
      margin-bottom: 16px;
    }

    .icon-marquee-row.reverse {
      animation: marquee-right 38s linear infinite;
    }

    .icon-pill {
      display: flex;
      align-items: center;
      gap: 10px;
      background: var(--surface-gray);
      border-radius: var(--radius-pill);
      padding: 10px 20px 10px 10px;
      flex-shrink: 0;
    }

    .icon-pill-circle {
      width: 36px;
      height: 36px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      font-weight: 700;
      color: #fff;
    }

    .icon-pill span {
      font-size: 14px;
      font-weight: 600;
      color: var(--primary-dark);
    }

    /* ===== Footer ===== */
    .footer {
      padding: 60px 0 32px;
      border-top: 1px solid var(--border);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-top: 12px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--primary-dark);
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-col a {
      font-size: 14px;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition);
    }

    .footer-col a:hover { color: var(--primary-dark); }

    .footer-bottom {
      border-top: 1px solid var(--border);
      padding-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }

    .footer-bottom p {
      font-size: 13px;
      color: var(--text-secondary);
    }

    .footer-bottom-links {
      display: flex;
      gap: 24px;
    }

    .footer-bottom-links a {
      font-size: 13px;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition);
    }

    .footer-bottom-links a:hover { color: var(--primary-dark); }

    /* ===== Mobile Responsive ===== */
    @media (max-width: 1024px) {
      .screenshot-grid { grid-template-columns: repeat(3, 1fr); }
      .tools-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .mobile-menu-btn { display: block; }

      .hero { padding: 48px 0 40px; }
      .hero h1 { font-size: 32px; }

      .stats-grid {
        grid-template-columns: 1fr;
        gap: 40px;
      }

      .screenshot-grid { grid-template-columns: repeat(2, 1fr); }

      .search-tabs {
        overflow-x: auto;
        max-width: 100%;
        scrollbar-width: none;
      }

      .search-tabs::-webkit-scrollbar { display: none; }

      .filter-pills {
        justify-content: flex-start;
        flex-wrap: nowrap;
      }

      .tools-grid { grid-template-columns: 1fr; }

      .flows-steps { gap: 12px; }
      .flow-step { width: 110px; height: 200px; }

      .testimonial-card { width: 300px; }

