  <script>
    // ===== Counter Animation =====
    const counters = document.querySelectorAll('.counter');
    let countersAnimated = false;

    function formatNumber(n) {
      return n.toLocaleString('en-US');
    }

    function animateCounters() {
      if (countersAnimated) return;
      countersAnimated = true;

      counters.forEach((counter, index) => {
        const target = parseInt(counter.dataset.target);
        const duration = 2000;
        const startDelay = index * 200;
        let startTime = null;

        setTimeout(() => {
          function step(timestamp) {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            counter.textContent = formatNumber(Math.floor(target * eased));
            if (progress < 1) {
              requestAnimationFrame(step);
            } else {
              counter.textContent = formatNumber(target);
            }
          }
          requestAnimationFrame(step);
        }, startDelay);
      });
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    statsObserver.observe(document.getElementById('stats'));

    // ===== Search Tabs =====
    const searchTabs = document.querySelectorAll('.search-tab');

    searchTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        searchTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        generateScreenshotGrid(tab.dataset.tab, document.querySelector('.filter-pill.active')?.dataset.filter || 'profile');
      });
    });

    // ===== Filter Pills =====
    const filterPills = document.querySelectorAll('.filter-pill');

    filterPills.forEach(pill => {
      pill.addEventListener('click', () => {
        filterPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        generateScreenshotGrid(document.querySelector('.search-tab.active')?.dataset.tab || 'screens', pill.dataset.filter);
      });
    });

    // ===== Screenshot Grid Generation =====
    const appNames = ['Spotify', 'Airbnb', 'Uber', 'Nike', 'Pinterest', 'Shopify', 'Notion', 'Figma', 'Slack', 'Stripe', 'Discord', 'Linear'];
    const colors = ['#E8E0F0', '#E0EBF0', '#F0E8E0', '#E0F0E4', '#F0E0E8', '#E4E0F0', '#F0ECE0', '#E0F0F0'];

    function seededRandom(seed) {
      let x = Math.sin(seed) * 10000;
      return x - Math.floor(x);
    }

    function generateScreenshotGrid(tab, filter) {
      const grid = document.getElementById('screenshot-grid');
      const seed = (tab + filter).split('').reduce((a, c) => a + c.charCodeAt(0), 0);
      let cards = '';
      const count = 8;

      for (let i = 0; i < count; i++) {
        const r = seededRandom(seed + i);
        const colorIdx = Math.floor(r * colors.length);
        const nameIdx = Math.floor(seededRandom(seed + i + 100) * appNames.length);
        cards += `
          <div class="screenshot-card" style="background:${colors[colorIdx]}">
            <div class="screenshot-placeholder">
              <div class="ph-header">
                <div class="ph-circle"></div>
                <div class="ph-bar short"></div>
              </div>
              <div class="ph-body">
                <div class="ph-rect"></div>
                <div class="ph-bar medium"></div>
                <div class="ph-bar short"></div>
              </div>
            </div>
            <span class="screenshot-card-label">${appNames[nameIdx]}</span>
          </div>`;
      }

      grid.style.opacity = '0';
      grid.style.transform = 'translateY(8px)';
      setTimeout(() => {
        grid.innerHTML = cards;
        requestAnimationFrame(() => {
          grid.style.transition = 'opacity 250ms ease, transform 250ms ease';
          grid.style.opacity = '1';
          grid.style.transform = 'translateY(0)';
        });
      }, 80);
    }

    generateScreenshotGrid('screens', 'profile');

    // ===== Flows Toggle =====
    const flowBtns = document.querySelectorAll('.flows-toggle-btn');
    const flowPanels = document.querySelectorAll('.flows-panel');

    flowBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        flowBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        flowPanels.forEach(p => p.classList.remove('active'));
        document.querySelector(`[data-panel="${btn.dataset.flow}"]`).classList.add('active');
      });
    });

    // ===== Testimonials =====
    const testimonials = [
      { name: 'Sebastian Speier', company: 'Shop', text: 'ScreenVault is a great resource and it always comes in handy to see what the best practices or standards are for mobile patterns in our current landscape.', initials: 'SS' },
      { name: 'Meng To', company: 'DesignCode', text: "ScreenVault is a game-changer for designers looking to step up their understanding of UX and UI design patterns. It's so massive, meticulously organized, has deep user flows and even a Figma plugin! It's indispensable in the modern designer's toolbox.", initials: 'MT' },
      { name: 'Marco Cornacchia', company: 'Figma', text: "ScreenVault is one of my favorite resources for product design and UI inspo. I love having access to a ton of 'real world examples' to see how different apps and companies handle specific UI patterns and flows.", initials: 'MC' },
      { name: 'Daryl Ginn', company: 'Endless', text: 'ScreenVault has quickly become our favourite inspiration resource for designing mobile apps at endless.design, their advanced filtering is unmatched in the inspiration space.', initials: 'DG' },
      { name: 'Rachel How', company: '', text: 'ScreenVault is my go-to reference for app & web design. Apart from saving countless hours, it gives me insights on the design patterns, copywriting, and user flows of world-class products. A must-have for creative inspiration and efficiency!', initials: 'RH' },
      { name: 'Haerin Song', company: 'Visa', text: 'By using the ScreenVault app, I save both my research time and space in my photo galleries filled with random screenshots. I love how easy it is to search for different patterns and copy and paste flows into Figma. It is a wonderful design tool you cannot live without!', initials: 'HS' }
    ];

    const avatarColors = ['#6C5CE7', '#00B894', '#E17055', '#0984E3', '#FDCB6E', '#E84393'];

    function makeCard(t, idx) {
