            ${companyLine}
          </div>
        </div>
        <div class="testimonial-text">"${t.text}"</div>
      </div>`;
    }

    const row1 = document.getElementById('testimonials-row-1');
    const row2 = document.getElementById('testimonials-row-2');
    const row1Data = [testimonials[0], testimonials[1], testimonials[2]];
    const row2Data = [testimonials[3], testimonials[4], testimonials[5]];

    let row1HTML = '', row2HTML = '';
    for (let dup = 0; dup < 4; dup++) {
      row1Data.forEach((t, i) => row1HTML += makeCard(t, i));
      row2Data.forEach((t, i) => row2HTML += makeCard(t, i + 3));
    }
    row1.innerHTML = row1HTML;
    row2.innerHTML = row2HTML;

    // ===== Brand Icon Marquee =====
    const brands = [
      { name: 'Coinbase', color: '#0052FF' },
      { name: 'Wise', color: '#9FE870' },
